/// <summary>
/// Creates a successful device info result.
/// </summary>
public static DeviceInfoResult Succeeded(DeviceInfo info, int? pinRetries = null, int? pukRetries = null) =>
    new() { Success = true, DeviceInfo = info, PinRetriesRemaining = pinRetries, PukRetriesRemaining = pukRetries };

/// <summary>
/// Creates a successful result with only retry information (no device info).
/// </summary>
public static DeviceInfoResult RetryInfoOnly(int? pinRetries, int? pukRetries) =>
    new() { Success = true, PinRetriesRemaining = pinRetries, PukRetriesRemaining = pukRetries };

    /// <summary>
    /// Creates a failed device info result.
    /// </summary>
    public static DeviceInfoResult Failed(string error) =>
        new() { Success = false, ErrorMessage = error };
}

/// <summary>
/// Gets whether the signing operation succeeded.
/// </summary>
public bool Success { get; init; }

/// <summary>
/// Gets the signature bytes when successful.
/// </summary>
public ReadOnlyMemory<byte> Signature { get; init; }

/// <summary>
/// Gets the time taken for the operation in milliseconds.
/// </summary>
public long ElapsedMilliseconds { get; init; }

/// <summary>
/// Creates a successful signing result.
/// </summary>
public static SigningResult Succeeded(ReadOnlyMemory<byte> signature, long elapsedMs) =>
    new() { Success = true, Signature = signature, ElapsedMilliseconds = elapsedMs };

/// <summary>
/// Gets whether the signature is valid (only meaningful when Success is true).
/// </summary>
public bool IsValid { get; init; }

/// <summary>
/// Creates a result indicating a valid signature.
/// </summary>
public static VerificationResult Valid(long elapsedMs) =>
    new() { Success = true, IsValid = true, ElapsedMilliseconds = elapsedMs };

/// <summary>
/// Creates a result indicating an invalid signature.
/// </summary>
public static VerificationResult Invalid(long elapsedMs) =>
    new() { Success = true, IsValid = false, ElapsedMilliseconds = elapsedMs };

