    public const int AdminData = 0x5FFF00;
}

/// <summary>
/// Extension methods for <see cref="IYubiKey"/> to create PIV sessions.
/// </summary>
public static class IYubiKeyExtensions
{
    extension(IYubiKey yubiKey)
    {

        /// <summary>
        /// Creates a PIV session with the YubiKey.
        /// </summary>
        /// <param name="options">Optional cross-cutting session creation settings.</param>
        /// <param name="cancellationToken">Cancellation token.</param>
        /// <returns>An initialized PIV session.</returns>
        /// <exception cref="NotSupportedException">If the YubiKey does not support PIV or SmartCard connections.</exception>
        public async Task<PivSession> CreatePivSessionAsync(
            SessionCreationOptions? options = null,
            CancellationToken cancellationToken = default)
        {
            var preferredConnectionType = options?.PreferredConnectionType;
            var transport = yubiKey.ResolveSessionTransport(
                preferredConnectionType,
                "PIV",
                ConnectionType.SmartCard);
            var sessionOptions = (options ?? new SessionCreationOptions())
                .WithPreferredConnectionType(transport);

            return await yubiKey.CreateSessionOverTransportAsync(
                    transport,
                    async (connection, ct) =>
                    {
                        var session = await PivSession.CreateAsync(
                                (ISmartCardConnection)connection,
                                sessionOptions,
                                ct)
                            .ConfigureAwait(false);
                        session.OwnConnection();
                        return session;
                    },
                    cancellationToken)
                .ConfigureAwait(false);
        }
    }
}

/// <summary>
/// PIV asymmetric key slots (key references in NIST SP 800-73) and their certificates.
/// </summary>
/// <remarks>Attestation (F9) is a Yubico extension, not a standard asymmetric key reference.</remarks>
public enum Slot : byte
{

    /// <summary>Attestation slot (F9).</summary>
    Attestation = 0xF9
}

/// <summary>
/// Touch policy for PIV private key usage.
/// </summary>
public enum TouchPolicy : byte
{

    /// <summary>Touch is cached for 15 seconds after first touch (requires YubiKey 4.3+).</summary>
    Cached = 0x03
}

/// <summary>Selects how PIV biometric user verification is performed.</summary>
public enum UserVerification
{

    /// <summary>Checks user-verification status without performing a verification ceremony.</summary>
    CheckOnly
}

[Fact]
public async Task GetPinOnlyModeAsync_NoAdminData_ReturnsNone()
{
    var backend = CreateBackend([0x6A, 0x82]); // File not found -> GetObjectAsync returns empty.

    var mode = await PinOnlyProtocol.GetPinOnlyModeAsync(backend, TestContext.Current.CancellationToken);

    Assert.Equal(PinOnlyMode.None, mode);
}

[Fact]
public async Task GetPinOnlyModeAsync_PinProtectedBitSet_ReturnsPinProtected()
{
    // ADMIN DATA inner content: 80 03 81 01 02 (PinProtected bit only), wrapped in 53 for GET DATA.
    byte[] adminData = [0x80, 0x03, 0x81, 0x01, 0x02];
    var backend = CreateBackend([0x53, (byte)adminData.Length, .. adminData, 0x90, 0x00]);

    var mode = await PinOnlyProtocol.GetPinOnlyModeAsync(backend, TestContext.Current.CancellationToken);

    Assert.Equal(PinOnlyMode.PinProtected, mode);
}

[Fact]
public async Task GetPinOnlyModeAsync_SaltPresent_ReturnsPinDerived()
{
    byte[] salt = new byte[16];
    byte[] adminData = [0x80, 0x15, 0x81, 0x01, 0x00, 0x82, 0x10, .. salt];
    var backend = CreateBackend([0x53, (byte)adminData.Length, .. adminData, 0x90, 0x00]);

    var mode = await PinOnlyProtocol.GetPinOnlyModeAsync(backend, TestContext.Current.CancellationToken);

    Assert.Equal(PinOnlyMode.PinDerived, mode);
}

[Fact]
public async Task GetPinOnlyModeAsync_MalformedAdminData_ReturnsBothUnavailable()
{
    // Data present but does not decode as ADMIN DATA (wrong outer tag 0x7F instead of 0x80).
    byte[] malformed = [0x7F, 0x02, 0xAA, 0xBB];
    var backend = CreateBackend([0x53, (byte)malformed.Length, .. malformed, 0x90, 0x00]);

    var mode = await PinOnlyProtocol.GetPinOnlyModeAsync(backend, TestContext.Current.CancellationToken);

    Assert.Equal(PinOnlyMode.PinProtectedUnavailable | PinOnlyMode.PinDerivedUnavailable, mode);
}

[Fact]
public void TryDecodePinProtectedManagementKey_Success_ZeroesInputBufferButNotExtractedKey()
{
    byte[] key = Enumerable.Range(1, 24).Select(i => (byte)i).ToArray();
    byte[] printed = [0x88, 0x1A, 0x89, 0x18, .. key];
    byte[] workingCopy = (byte[])printed.Clone();

    bool found = PinOnlyProtocol.TryDecodePinProtectedManagementKey(workingCopy, out var extractedKey);

    Assert.True(found);
    Assert.Equal(key, extractedKey.ToArray());

    // ISC-16 family: the raw PRINTED-object bytes (containing the clear-text key) must be
    // zeroed once this method is done with them, regardless of whether it found a key.
    Assert.All(workingCopy, b => Assert.Equal(0, b));
}

[Fact]
public void TryDecodePinProtectedManagementKey_WrongOuterTag_StillZeroesInputBuffer()
{
    byte[] key = Enumerable.Range(1, 24).Select(i => (byte)i).ToArray();
    byte[] notPinProtected = [0x89, 0x18, .. key]; // wrong outer tag (0x89 instead of 0x88)
    byte[] workingCopy = (byte[])notPinProtected.Clone();

    bool found = PinOnlyProtocol.TryDecodePinProtectedManagementKey(workingCopy, out var extractedKey);

    Assert.False(found);
    Assert.True(extractedKey.IsEmpty);
    Assert.All(workingCopy, b => Assert.Equal(0, b));
}

    [Fact]
    public void TryDecodePinProtectedManagementKey_NoManagementKeyPresent_StillZeroesInputBuffer()
    {
        byte[] emptyPinProtected = [0x88, 0x00]; // "cleared" PIN-protected marker, no management key
        byte[] workingCopy = (byte[])emptyPinProtected.Clone();

        bool found = PinOnlyProtocol.TryDecodePinProtectedManagementKey(workingCopy, out var extractedKey);

        Assert.False(found);
        Assert.True(extractedKey.IsEmpty);
        Assert.All(workingCopy, b => Assert.Equal(0, b));
    }
}

[Fact]
public void AppendTlvZeroingPrevious_ReturnsCorrectConcatenation()
{
    byte[] previous = Enumerable.Range(1, 24).Select(i => (byte)i).ToArray();
    byte[] previousSnapshot = (byte[])previous.Clone();
    using var tlv = new Tlv(0xAA, [0x02]);

    var result = KeyProtocol.AppendTlvZeroingPrevious(previous, tlv);

    byte[] expected = [.. previousSnapshot, .. tlv.AsSpan()];
    Assert.Equal(expected, result);
}

[Fact]
public void AppendTlvZeroingPrevious_ZeroesThePreviousArray()
{
    byte[] previous = Enumerable.Range(1, 24).Select(i => (byte)i).ToArray();
    using var tlv = new Tlv(0xAA, [0x02]);

    _ = KeyProtocol.AppendTlvZeroingPrevious(previous, tlv);

    Assert.All(previous, b => Assert.Equal(0, b));
}

    [Fact]
    public void AppendTlvZeroingPrevious_ChainedForBothPolicies_ZeroesEveryIntermediateArray()
    {
        // Mirrors ImportKeyAsync's real usage: append pin-policy TLV, then touch-policy TLV.
        // Both the original raw key-encoding array AND the first (pin-policy-appended)
        // concatenation must end up zeroed - only the final array should remain live.
        byte[] originalKeyData = Enumerable.Range(1, 32).Select(i => (byte)i).ToArray();
        byte[] originalSnapshot = (byte[])originalKeyData.Clone();

        using var pinTlv = new Tlv(0xAA, [(byte)PinPolicy.Once]);
        using var touchTlv = new Tlv(0xAB, [(byte)TouchPolicy.Always]);

        var afterPin = KeyProtocol.AppendTlvZeroingPrevious(originalKeyData, pinTlv);

        // The original array is now orphaned by the reassignment pattern in ImportKeyAsync -
        // it must already be zeroed at this point, not just eventually by some later cleanup.
        Assert.All(originalKeyData, b => Assert.Equal(0, b));

        var afterTouch = KeyProtocol.AppendTlvZeroingPrevious(afterPin, touchTlv);

        // The first intermediate concatenation is now itself orphaned and must be zeroed too.
        Assert.All(afterPin, b => Assert.Equal(0, b));

        byte[] expectedFinal = [.. originalSnapshot, .. pinTlv.AsSpan(), .. touchTlv.AsSpan()];
        Assert.Equal(expectedFinal, afterTouch);
    }
}
